# ╔═╡ 3b95f760-10ac-453f-b7b8-41deea76f3f0
md"""
## Part 3: Work with an agent on MRI tasks

The Bloch sphere shows the magnetization vector in three dimensions. In the following plot, each colored line from the center represents a simulated spin at position ``z`` along the slice; its endpoint gives ``(M_x, M_y, M_z)``. The color bar identifies ``z``, and the fading trail shows recent motion.

With slice-selective excitation, spins at different ``z`` positions experience different resonance frequencies and follow different magnetization trajectories.

!!! info "Instructions"
    Ask your coding agent to make these changes. It should clarify missing values before editing, then help you interpret the results.

    1. **Make the excited slice thinner.** Agree on a new thickness, then use the time slider to compare the result.
    2. **Change the flip angle.** Agree on a new angle, then compare how the spins respond.
"""

# ╔═╡ 7542e835-0be7-4ab6-aef8-57853244d139
seq = PulseDesigner.build_sinc_pulse(
    π / 2;
    duration=2e-3,
    slice_thickness=5e-3,
    sys=Scanner(limits=HardwareLimits(Gmax=20e-3))
)

# ╔═╡ d4aa4400-f789-444d-84cb-73043a464dba
function bloch_sphere_trajectory(seq)
    positions = collect(range(-3e-3, 3e-3; length=9))
    n = length(positions)
    obj = Phantom(x=zeros(n), z=positions, T1=fill(Inf, n), T2=fill(Inf, n))
    times = [0.0]
    transverse = [zeros(ComplexF64, n)]
    longitudinal = [ones(n)]
    record = function (progress, blocks, data, params)
        push!(times, data.seqd.t[last(blocks.parts[progress.block])])
        push!(transverse, copy(data.Xt.xy))
        push!(longitudinal, copy(data.Xt.z))
    end
    simulate(obj, seq, Scanner(); verbose=false, callbacks=(record,), sim_params=Dict(
        "gpu" => false, "Nthreads" => 1, "precision" => "f64",
        "max_block_length" => 1, "max_rf_block_length" => 1,
        "Δt" => 10e-6, "Δt_rf" => 10e-6, "return_type" => "state",
    ))
    mx = real.(hcat(transverse...))
    my = imag.(hcat(transverse...))
    mz = hcat(longitudinal...)
    t_ms = 1e3 .* times
    colors = ["#2166ac", "#3e5cba", "#6051bb", "#8244b4", "#a1379f",
              "#b52e83", "#c22d62", "#c32c43", "#b2182b"]
    colorscale = [[t, c] for (t, c) in zip(range(0, 1; length=n), colors)]
    θ, φ = range(0, π; length=25), range(0, 2π; length=49)
    sphere = surface(
        x=[sin(a) * cos(b) for a in θ, b in φ],
        y=[sin(a) * sin(b) for a in θ, b in φ],
        z=[cos(a) for a in θ, b in φ],
        surfacecolor=zeros(length(θ), length(φ)),
        colorscale=[[0, "#94a3b8"], [1, "#94a3b8"]], opacity=0.12,
        showscale=false, hoverinfo="skip", showlegend=false,
    )
    function spin_traces(k)
        spin_data = GenericTrace[]
        first_point = searchsortedfirst(times, times[k] - 0.1 * times[end])
        trail_edges = round.(Int, range(first_point, k; length=5))
        for j in eachindex(positions)
            for segment in 1:4
                trail = trail_edges[segment]:trail_edges[segment + 1]
                push!(spin_data, scatter3d(
                    x=mx[j, trail], y=my[j, trail], z=mz[j, trail], mode="lines",
                    line=attr(color=colors[j], width=3), opacity=0.15 + 0.2 * (segment - 1),
                    name="z = $(round(1e3 * positions[j]; digits=2)) mm", legendgroup=string(j),
                    hoverinfo="name", showlegend=false,
                ))
            end
            push!(spin_data, scatter3d(
                x=[0, mx[j, k]], y=[0, my[j, k]], z=[0, mz[j, k]],
                mode="lines+markers", line=attr(color=colors[j], width=6),
                marker=attr(color=fill(1e3 * positions[j], 2), colorscale=colorscale,
                    cmin=-3, cmax=3, showscale=j == n, size=[0, 4],
                    colorbar=attr(title=attr(text="z-position (mm)", side="right"),
                        tickvals=[-3, 0, 3], thickness=12, len=0.7, outlinewidth=0),
                    line=attr(color="#64748b", width=1)),
                legendgroup=string(j), showlegend=false, hoverinfo="skip",
            ))
        end
        spin_data
    end
    traces = [sphere; spin_traces(length(times))]
    indices = unique(round.(Int, range(1, length(times); length=min(100, length(times)))))
    frames = [frame(name=string(k), data=spin_traces(k),
        traces=collect(1:(length(traces) - 1))) for k in indices]
    immediate = attr(mode="immediate", transition=attr(duration=0),
        frame=attr(duration=0, redraw=true))
    axis_style = attr(range=[-1.1, 1.1], showbackground=false,
        showgrid=true, gridcolor="#94a3b8", gridwidth=1,
        showline=true, linecolor="#64748b", zerolinecolor="#64748b",
        ticks="outside", tickcolor="#64748b", tickfont=attr(color="#334155"))
    layout = Layout(
        height=430, margin=attr(l=0, r=70, t=0, b=70),
        paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(0,0,0,0)",
        font=attr(family="Arial, sans-serif", color="#475569"),
        showlegend=false,
        scene=attr(aspectmode="cube", uirevision="compact-labels",
            xaxis=merge(axis_style, attr(title="Mₓ")),
            yaxis=merge(axis_style, attr(title="Mᵧ")),
            zaxis=merge(axis_style, attr(title="M𝓏")),
            camera=attr(eye=attr(x=1.15, y=1.15, z=0.7))),
        sliders=[attr(active=length(indices)-1, x=0, len=1, y=0, pad=attr(t=0, b=0),
            font=attr(color="rgba(0,0,0,0)"),
            currentvalue=attr(prefix="Time: ", suffix=" ms", font=attr(color="#475569")),
            steps=[attr(label=string(round(t_ms[k]; digits=2)), method="animate",
                args=[[string(k)], immediate]) for k in indices])],
        uirevision="bloch-sphere",
    )
    p = PlutoPlotly.plot(traces, layout, frames; config=PlotConfig(displaylogo=false, displayModeBar=false))
    push_script!(p, htl_js("""
        let sliderDragging = false;
        PLOT.addEventListener("mousedown", event => {
            sliderDragging = event.target.closest(".slider-container") !== null;
        }, {capture: true, signal: controller.signal});
        function finishSliderDrag() {
            if (!sliderDragging) return;
            sliderDragging = false;
            PLOT.dispatchEvent(new MouseEvent("mouseup", {bubbles: false, buttons: 0}));
        }
        window.addEventListener("mouseup", finishSliderDrag, {capture: true, signal: controller.signal});
        window.addEventListener("blur", finishSliderDrag, {signal: controller.signal});
        window.addEventListener("mousemove", event => {
            if (event.buttons === 0) finishSliderDrag();
        }, {capture: true, signal: controller.signal});
    """))
    p
end

